class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        i, j = 0, len(nums) - 1
        left, right, ops = nums[0], nums[-1], 0
        while i < j:
            if left < right:
                i += 1; left += nums[i]; ops += 1
            elif left > right:
                j -= 1; right += nums[j]; ops += 1
            else:
                i += 1; j -= 1
                if i < j:
                    left, right = nums[i], nums[j]
        return ops

