class Solution {
public:
    int minimumOperations(vector<int>& nums) {
        int i = 0, j = nums.size() - 1, ops = 0;
        long long left = nums[0], right = nums.back();
        while (i < j) {
            if (left < right) { left += nums[++i]; ops++; }
            else if (left > right) { right += nums[--j]; ops++; }
            else { i++; j--; if (i < j) { left = nums[i]; right = nums[j]; } }
        }
        return ops;
    }
};

