class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [[0]*n for _ in range(n)]
        for ln in range(2, n+1):
            for l in range(n-ln+1):
                r = l+ln-1
                if nums[l] == nums[r]:
                    dp[l][r] = dp[l+1][r-1] if r-l > 1 else 0
                else:
                    dp[l][r] = 1 + min(dp[l+1][r], dp[l][r-1])
        return dp[0][n-1]

