class Solution {
public:
    int minimumOperations(vector<int>& nums) {
        int n = nums.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int len = 2; len <= n; len++)
            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;
                if (nums[l] == nums[r]) dp[l][r] = (r - l > 1) ? dp[l+1][r-1] : 0;
                else dp[l][r] = 1 + min(dp[l+1][r], dp[l][r-1]);
            }
        return dp[0][n-1];
    }
};

